def transform(grid):
    """Recolor any uniformly colored full row or column to 2."""
    h, w = len(grid), len(grid[0])
    horizontal = {r for r, row in enumerate(grid) if len(set(row)) == 1}
    vertical = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}
    return [[2 if r in horizontal or c in vertical else value
             for c, value in enumerate(row)]
            for r, row in enumerate(grid)]
